INSERT INTO site_stories (slug, title, tagline, kind, body, stats, cover_url, photos, results_url, gallery_url, is_published, sort_order) VALUES ('smc2025', 'Society Mafia Cup 2025', 'Самый большой турнир в Кабардино-Балкарии', 'tournament', 'Ежегодный турнир по спортивной мафии от клуба TITAN KBR собирает сильнейших игроков региона, чтобы определить лучшего мафиозного стратега года.

Напряжённые партии, профессиональное судейство и атмосфера интеллектуального поединка: каждый раунд — сражение разума, логики и интуиции, где решает одна фраза.

Society Mafia Cup — больше, чем турнир: встреча единомышленников и праздник для всех, кто живёт игрой. Финалисты получают призы, признание сообщества и место в истории TITAN KBR.', '[{"value":"30","label":"участников"},{"value":"50 000 ₽","label":"призовой фонд"},{"value":"1721","label":"ELO турнира"}]'::jsonb, '/media/smc2025-1-1600.webp', '["/media/smc2025-1-1600.webp","/media/smc2025-2-1600.webp","/media/smc2025-3-1600.webp"]'::jsonb, 'https://gomafia.pro/tournament/1982', 'https://drive.google.com/drive/folders/1JhJjbJ77u-ZVGnFhV6w9SpHlW1vsdv9T?usp=sharing', true, 80) ON CONFLICT (slug) DO NOTHING;
INSERT INTO site_stories (slug, title, tagline, kind, body, stats, cover_url, photos, results_url, gallery_url, is_published, sort_order) VALUES ('friendscup', 'Friends Cup', 'Мафия, как в хорошей компании', 'tournament', 'Миникап под тематикой легендарного сериала «Друзья»: 10 игроков из Нальчика, Владикавказа, Ессентуков, Минеральных Вод и Пятигорска провели день, полный смеха и мафиозных интриг.

Этот миникап не про соперничество — он про дружбу, эмоции и удовольствие от игры. Место за столом нашлось для всех, как в Центральной кофейне.', '[{"value":"10","label":"участников"},{"value":"5","label":"городов"},{"value":"1570","label":"ELO турнира"}]'::jsonb, '/media/friendscup-1-1600.webp', '["/media/friendscup-1-1600.webp","/media/friendscup-2-1600.webp","/media/table-night-1600.webp"]'::jsonb, 'https://gomafia.pro/tournament/2271', 'https://drive.google.com/drive/folders/1JhJjbJ77u-ZVGnFhV6w9SpHlW1vsdv9T?usp=sharing', true, 70) ON CONFLICT (slug) DO NOTHING;
INSERT INTO site_stories (slug, title, tagline, kind, body, stats, cover_url, photos, results_url, gallery_url, is_published, sort_order) VALUES ('girlcup', 'Женский миникап', 'Игра со стилем', 'tournament', 'Girl power в мафии: за игровые столы сели только девушки из Нальчика, Владикавказа, Минеральных Вод, Пятигорска и Ессентуков.

День азарта, улыбок и командного духа, а на память — бьюти-подарки от партнёров турнира. Мафия, которая звучит по-новому.', '[{"value":"10","label":"участниц"},{"value":"3","label":"города"},{"value":"1384","label":"ELO турнира"}]'::jsonb, '/media/girlcup-1-1600.webp', '["/media/girlcup-1-1600.webp","/media/girlcup-2-1600.webp","/media/girlcup-3-1600.webp"]'::jsonb, 'https://gomafia.pro/tournament/1250', 'https://drive.google.com/drive/folders/1_nnKEVu_I3lqNHhViKBqkGrl28rvzWD7?usp=sharing', true, 60) ON CONFLICT (slug) DO NOTHING;
INSERT INTO site_stories (slug, title, tagline, kind, body, stats, cover_url, photos, results_url, gallery_url, is_published, sort_order) VALUES ('5y', '5 лет клубу Titan KBR', 'Эпоха гангстеров и блеска', 'party', 'Клуб отметил пятый день рождения вечеринкой в духе мафии 20-х: джаз, костюмы в стиле Гэтсби, шляпы, перья и блеск бокалов — настоящее подпольное казино золотой эпохи Чикаго.

За столами — коварные мафиози и обаятельные леди, за кадром — смех, музыка и лучшие моменты пяти лет. И это только начало.', '[{"value":"50","label":"гостей"},{"value":"4","label":"города"},{"value":"10","label":"часов веселья"}]'::jsonb, '/media/5y-1-1600.webp', '["/media/5y-1-1600.webp","/media/5y-2-1600.webp","/media/5y-3-1600.webp"]'::jsonb, NULL, 'https://drive.google.com/drive/folders/1MCA-ltEV3yHALo7j4c44OLc9gskTjL05?usp=sharing', true, 50) ON CONFLICT (slug) DO NOTHING;
INSERT INTO site_stories (slug, title, tagline, kind, body, stats, cover_url, photos, results_url, gallery_url, is_published, sort_order) VALUES ('halloween', 'Halloween 2025', 'Ночь, где мафия оживает', 'party', 'Halloween Mafia Party: костюмы, маски и игры до глубокой ночи. Гости приехали из семи городов, чтобы найти мафию среди нечисти.', '[{"value":"60","label":"гостей"},{"value":"7","label":"городов"},{"value":"9","label":"часов веселья"}]'::jsonb, '/media/halloween-1-1600.webp', '["/media/halloween-1-1600.webp","/media/halloween-2-1600.webp","/media/halloween-3-1600.webp"]'::jsonb, NULL, 'https://drive.google.com/drive/folders/1ILzGwMEa-h4HOsMmU-6rBA5lb3PBYiRw?usp=sharing', true, 40) ON CONFLICT (slug) DO NOTHING;
INSERT INTO site_stories (slug, title, tagline, kind, body, stats, cover_url, photos, results_url, gallery_url, is_published, sort_order) VALUES ('meladzecup', 'Meladze Cup', 'Мафия под музыку, которая трогает душу', 'tournament', 'Особенный миникап, посвящённый творчеству Валерия Меладзе: весь вечер за столами звучали его лучшие хиты.

Игроки из Нальчика, Владикавказа, Ессентуков, Пятигорска и Минеральных Вод, а в финале — подарок каждому на память. Там, где звучит Меладзе, игра превращается в историю.', '[{"value":"10","label":"участников"},{"value":"4","label":"города"},{"value":"1492","label":"ELO турнира"}]'::jsonb, '/media/meladzecup-1-1600.webp', '["/media/meladzecup-1-1600.webp","/media/meladzecup-2-1600.webp","/media/meladzecup-3-1600.webp"]'::jsonb, 'https://gomafia.pro/tournament/1380', 'https://drive.google.com/drive/folders/1ZyshOOKNrG4B4i1ovLV_FEAq1BPDwrDr?usp=sharing', true, 30) ON CONFLICT (slug) DO NOTHING;
INSERT INTO site_stories (slug, title, tagline, kind, body, stats, cover_url, photos, results_url, gallery_url, is_published, sort_order) VALUES ('smc2022', 'Society Mafia Cup 2022', 'Старт новой эры мафии', 'tournament', 'С этого турнира началась история больших мафиозных сражений TITAN KBR: игроки из девяти городов открыли новую страницу спортивной мафии в регионе.

Каждая партия — мини-триллер с неожиданными поворотами. Здесь родилась традиция, которая ежегодно объединяет лучших.', '[{"value":"40","label":"участников"},{"value":"9","label":"городов"},{"value":"1240","label":"ELO турнира"}]'::jsonb, '/media/smc2022-1-1600.webp', '["/media/smc2022-1-1600.webp","/media/smc2022-2-1600.webp","/media/smc2022-3-1600.webp"]'::jsonb, 'https://gomafia.pro/tournament/72', 'https://drive.google.com/drive/folders/1T1IKM7QZyJeDCoa6KB6s_8_fZueDacIU?usp=sharing', true, 20) ON CONFLICT (slug) DO NOTHING;
INSERT INTO site_stories (slug, title, tagline, kind, body, stats, cover_url, photos, results_url, gallery_url, is_published, sort_order) VALUES ('emc2021', 'Elbrus Mafia Cup 2021', 'Мафия на высоте', 'tournament', 'Самый высокогорный турнир по мафии в истории: на склонах Эльбруса, под облаками, собрались лучшие игроки из разных городов.

Каждый раунд — на фоне Кавказа, где стратегия и интуиция звучат в гармонии с природой. Легендарная веха в истории TITAN KBR.', '[{"value":"20","label":"участников"},{"value":"5","label":"городов"},{"value":"3","label":"дня"}]'::jsonb, '/media/emc2021-1-1600.webp', '["/media/emc2021-1-1600.webp","/media/emc2021-2-1600.webp","/media/emc2021-3-1600.webp"]'::jsonb, 'https://mafiaworldtour.org/tournaments/1279', 'https://drive.google.com/drive/folders/1Kw-fR9QgWN7s7LzAcTUafyXIua_P_olQ?usp=sharing', true, 10) ON CONFLICT (slug) DO NOTHING;
